defmodule Mix.Tasks.Flint.UpdateTest do
  use ExUnit.Case, async: true

  import Igniter.Test

  alias FlintUI.Generator

  @path "lib/my_app_web/components.ex"

  defp content(igniter) do
    igniter.rewrite.sources[@path]
    |> Rewrite.Source.get(:content)
  end

  defp module_source(wrappers) do
    """
    defmodule MyAppWeb.Components do
      use Phoenix.Component

    #{wrappers}
    end
    """
  end

  # An out-of-date wrapper that still matches its recorded hash: exactly what a
  # wrapper generated by an older library looks like.
  defp outdated_button do
    body =
      Generator.component_body(:button)
      |> String.replace(~s(default: "surface"), ~s(default: "solid"))

    marker =
      Generator.component_source(:button)
      |> String.split("\n")
      |> List.first()
      |> String.replace("lib=#{Generator.library_version()}", "lib=0.0.0")
      |> Generator.with_hash(Generator.body_hash(body))

    marker <> "\n" <> body
  end

  # A wrapper the user has edited by hand: the body no longer matches the hash.
  defp edited_button do
    outdated_button()
    |> String.replace(~s(default: "solid"), ~s(default: "custom"))
  end

  test "refreshes a pristine wrapper to the current body" do
    igniter =
      test_project(app_name: :my_app, files: %{@path => module_source(outdated_button())})
      |> Igniter.compose_task("flint.update", ["button", "--no-theme"])

    source = content(igniter)

    refute source =~ ~s(default: "solid")
    assert source =~ ~s(default: "surface")
    assert source =~ "wrapper_api=#{Generator.wrapper_api()}"
    assert source =~ "lib=#{Generator.library_version()}"

    assert_has_notice(igniter, fn notice -> notice =~ "button: refreshed" end)
  end

  test "leaves a wrapper from the current version untouched" do
    current = Generator.component_source(:button)
    expected = module_source(current)

    igniter =
      test_project(app_name: :my_app, files: %{@path => expected})
      |> Igniter.compose_task("flint.update", ["button", "--no-theme"])

    assert content(igniter) == expected
  end

  test "leaves an edited wrapper alone and warns" do
    igniter =
      test_project(app_name: :my_app, files: %{@path => module_source(edited_button())})
      |> Igniter.compose_task("flint.update", ["button", "--no-theme"])

    assert content(igniter) =~ ~s(default: "custom")
    assert content(igniter) =~ "lib=0.0.0"

    assert_has_warning(igniter, fn warning ->
      warning =~ "button has local changes"
    end)
  end

  test "--force overwrites an edited wrapper" do
    igniter =
      test_project(app_name: :my_app, files: %{@path => module_source(edited_button())})
      |> Igniter.compose_task("flint.update", ["button", "--force", "--no-theme"])

    refute content(igniter) =~ ~s(default: "custom")
    assert content(igniter) =~ ~s(default: "surface")
  end

  test "--force keeps code added below the generated block" do
    seed = module_source(outdated_button() <> "\n\ndef custom, do: :ok")

    igniter =
      test_project(app_name: :my_app, files: %{@path => seed})
      |> Igniter.compose_task("flint.update", ["button", "--force", "--no-theme"])

    assert content(igniter) =~ ~s(default: "surface")
    assert content(igniter) =~ "def custom, do: :ok"
  end

  test "warns instead of downgrading a wrapper from a newer library" do
    newer =
      outdated_button()
      |> String.replace("wrapper_api=#{Generator.wrapper_api()}", "wrapper_api=999")

    igniter =
      test_project(app_name: :my_app, files: %{@path => module_source(newer)})
      |> Igniter.compose_task("flint.update", ["button", "--no-theme"])

    assert content(igniter) =~ "wrapper_api=999"
    assert_has_warning(igniter, fn warning -> warning =~ "newer wrapper API" end)
  end

  test "reports components available in the library but not generated" do
    igniter =
      test_project(app_name: :my_app, files: %{@path => module_source(outdated_button())})
      |> Igniter.compose_task("flint.update", ["--no-theme"])

    assert_has_notice(igniter, fn notice -> notice =~ "not generated in this module" end)
  end

  test "reports an unknown component" do
    igniter =
      test_project(app_name: :my_app, files: %{@path => module_source(outdated_button())})
      |> Igniter.compose_task("flint.update", ["nope", "--no-theme"])

    assert_has_issue(igniter, fn issue -> issue =~ "Unknown component" end)
  end

  test "missing components module is an issue" do
    igniter =
      test_project(app_name: :my_app)
      |> Igniter.compose_task("flint.update", ["--no-theme"])

    assert_has_issue(igniter, fn issue -> issue =~ "was not found" end)
  end

  test "refreshes the theme stylesheets by default" do
    igniter =
      test_project(
        app_name: :my_app,
        files: %{
          @path => module_source(outdated_button()),
          "assets/css/app.css" => ~s(@import "tailwindcss";\n)
        }
      )
      |> Igniter.compose_task("flint.update", ["button"])

    assert_creates(igniter, "assets/css/flint.css")
    assert_creates(igniter, "assets/css/flint-utilities.css")
  end
end
